"""Small dependency-free management page served by the standalone Body host."""

BODY_GUI_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>Body Runtime</title>
<style>
:root{color-scheme:dark;font:14px system-ui,sans-serif;background:#09110e;color:#dce9df}
body{max-width:1180px;margin:0 auto;padding:28px;background:#09110e}h1{font-size:28px;margin:4px 0}p{color:#8fa99a}.eyebrow{color:#83d5ae;font:11px ui-monospace,monospace;letter-spacing:.12em}
header{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;border-bottom:1px solid #294137;padding-bottom:20px;margin-bottom:20px}.actions{display:flex;gap:8px;flex-wrap:wrap}button{border:1px solid #4b8c6b;background:#10251b;color:#d9f5e5;padding:9px 12px;cursor:pointer;border-radius:4px}button:hover{background:#1b3b29}
 .stats{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:16px}.stat,.panel{border:1px solid #294137;background:#101c16;padding:14px}.stat span{display:block;color:#789589;font-size:10px;text-transform:uppercase}.stat b{display:block;margin-top:8px;font:16px ui-monospace,monospace}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.panel h2{font-size:12px;color:#9dd7b5;text-transform:uppercase;letter-spacing:.08em;margin:0 0 12px}.plugin{display:flex;justify-content:space-between;border-top:1px solid #24372d;padding:10px 0}.plugin small{display:block;color:#789589;margin-top:3px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#747f78;margin-right:7px}.dot.on{background:#76e0a6;box-shadow:0 0 0 3px #76e0a622}.map-layout{display:grid;grid-template-columns:minmax(0,1fr) 190px;gap:12px;align-items:start}.map{width:100%;aspect-ratio:1;background:#07120f;border:1px solid #315544}.map text{fill:#d8f2e4;font:2.8px ui-monospace,monospace;font-weight:700;text-anchor:middle;dominant-baseline:middle}.map .grid{stroke:#17352d;stroke-width:.08}.map .room{fill:#0a1915;stroke:#6aa88b;stroke-width:.18}.map .body{fill:#b6f1d3}.map .target{fill:#efb17d}.map .obstacle{fill:#9b819a}.map .goal{fill:none;stroke:#e5d17b;stroke-width:.18;stroke-dasharray:.4 .2}.scene-legend{display:flex;flex-direction:column;gap:7px;max-height:420px;overflow:auto}.scene-item{display:grid;grid-template-columns:24px minmax(0,1fr);gap:7px;align-items:center;border-top:1px solid #24372d;padding:7px 0;font-size:11px}.scene-item i{display:grid;place-items:center;width:22px;height:22px;border-radius:50%;background:#789589;color:#07120f;font:11px ui-monospace,monospace;font-style:normal;font-weight:700}.scene-item i.body{background:#b6f1d3}.scene-item i.target{background:#efb17d}.scene-item i.obstacle{background:#9b819a}.scene-item b{display:block;color:#c6dfd1}.scene-item small{display:block;color:#789589;margin-top:2px}.map-actions{display:flex;justify-content:flex-end;margin:10px 0}.map-expand{font-size:12px}.map-modal{position:fixed;inset:0;z-index:10;display:none;place-items:center;background:#020806ee;padding:28px}.map-modal.open{display:grid}.map-modal-inner{width:min(92vw,1100px);height:min(92vh,900px);display:flex;flex-direction:column;border:1px solid #4c896b;background:#0b1812;padding:18px;box-shadow:0 20px 80px #000}.map-modal-head{display:flex;align-items:center;justify-content:space-between;gap:12px;color:#b9d8ca;margin-bottom:12px}.map-modal-head h2{margin:0;font-size:14px;text-transform:uppercase;letter-spacing:.08em}.map-modal-close{font-size:20px;padding:4px 10px}.map-expanded-layout{display:grid;grid-template-columns:minmax(0,1fr) 230px;gap:16px;min-height:0;flex:1}.map-large{display:block;width:100%;height:100%;min-height:0;background:#07120f;border:1px solid #315544}.map-large text{fill:#d8f2e4;font:1.8px ui-monospace,monospace;font-weight:700;text-anchor:middle;dominant-baseline:middle}.map-large .grid{stroke:#1d4437;stroke-width:.05}.map-large .room{fill:#0a1915;stroke:#6aa88b;stroke-width:.12}.map-large .body{fill:#b6f1d3}.map-large .target{fill:#efb17d}.map-large .obstacle{fill:#9b819a}.map-large .goal{fill:none;stroke:#e5d17b;stroke-width:.12;stroke-dasharray:.28 .14}.log{white-space:pre-wrap;overflow:auto;max-height:300px;background:#071019;color:#a8d9c2;padding:12px;font:11px/1.5 ui-monospace,monospace}.muted{color:#789589}.wide{grid-column:1/-1}@media(max-width:760px){header{display:block}.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.actions{margin-top:14px}.map-layout,.map-expanded-layout{grid-template-columns:1fr}.scene-legend{max-height:180px}.grid{grid-template-columns:1fr}.actions{margin-top:14px}.map-modal{padding:10px}.map-modal-inner{width:96vw;height:94vh;padding:10px}}
/* Body management layout: keep controls, perception, and visualization in separate visual lanes. */
*{box-sizing:border-box}body{max-width:1280px;min-width:0;line-height:1.4}.grid{grid-template-columns:minmax(300px,.82fr) minmax(0,1.45fr);align-items:start}.panel{min-width:0;overflow:hidden}.panel h2{line-height:1.2}.plugin-settings{display:grid;gap:10px;margin-top:4px;padding:14px;background:#0b1711;border:1px solid #294137}.plugin-settings[hidden]{display:none}.plugin-settings label{display:grid;gap:5px;color:#9db9aa;font-size:11px}.plugin-settings input:not([type=checkbox]){width:100%;min-width:0;background:#0a120e;border:1px solid #385746;border-radius:4px;color:#d9f5e5;padding:9px 10px;font:12px ui-monospace,monospace}.plugin-settings label:has(input[type=checkbox]){display:flex;align-items:center;gap:8px}.plugin-settings input[type=checkbox]{width:17px;height:17px;accent-color:#76e0a6}.plugin-settings button{justify-self:start}.map-layout{grid-template-columns:minmax(0,1fr) 180px}.map{display:block;min-width:0}.scene-legend{min-width:0}.log{min-width:0;overflow:auto}.panel.wide{grid-column:1/-1}.panel.wide .log{max-height:260px;min-height:120px}@media(max-width:860px){body{padding:18px}.grid{grid-template-columns:1fr}.stats{grid-template-columns:repeat(3,1fr)}.panel.wide{grid-column:auto}}@media(max-width:560px){.stats{grid-template-columns:repeat(2,1fr)}header{gap:14px}.map-layout{grid-template-columns:1fr}.scene-legend{max-height:220px}}
</style>
</head>
<body>
<header><div><div class="eyebrow">COGNITIVE ORGANISM / BODY</div><h1>Independent Body Runtime</h1><p>Sensors, plugins and embodied world model. This page is served by the Body itself.</p></div><div class="actions"><button onclick="step()">Run supervised step</button><button onclick="resetModel()">Reset simulation</button><button onclick="refresh()">Refresh</button></div></header>
<div id="message" class="muted">Connecting to Body...</div><section class="stats"><div class="stat"><span>Runtime</span><b id="runtime">—</b></div><div class="stat"><span>World model</span><b id="mode">—</b></div><div class="stat"><span>Source</span><b id="source">—</b></div><div class="stat"><span>Steps</span><b id="steps">—</b></div><div class="stat"><span>Observation</span><b id="observation">—</b></div></section>
<div class="grid"><section class="panel"><h2>Body plugins</h2><div id="plugins" class="muted">Loading...</div><div id="home-assistant-settings" class="plugin-settings" hidden><h2 style="margin-top:24px">Home Assistant plugin</h2><label>URL<input id="ha-url" type="url" placeholder="http://homeassistant:8123"></label><label>Long-lived access token<input id="ha-token" type="password" placeholder="Leave blank to keep the current token"></label><label>Polling interval (seconds)<input id="ha-poll" type="number" min="1" step="1"></label><label>Allowed domains<input id="ha-domains" placeholder="Empty means all domains"></label><label>Entities presented to the Brain<input id="ha-entities" placeholder="Comma-separated entity IDs"></label><label><input id="ha-verify" type="checkbox"> Verify HTTPS certificate</label><button onclick="saveHomeAssistantSettings()">Save Home Assistant settings</button></div><h2 style="margin-top:24px">Latest Body perception</h2><div id="perception" class="log">Waiting for an observation.</div></section><section class="panel"><h2>Embodied map</h2><div class="map-actions"><button class="map-expand" onclick="expandMap()">Expand readable map</button></div><div class="map-layout"><svg id="map" class="map" viewBox="0 0 12 12" aria-label="Body world map"></svg><div id="map-legend" class="scene-legend"><span class="muted">No scene available.</span></div></div><div id="map-note" class="muted">No simulated scene available.</div></section><section class="panel wide"><h2>World Model status</h2><div id="status" class="log">Loading...</div></section></div><div id="map-modal" class="map-modal" role="dialog" aria-modal="true" aria-label="Expanded Body world map"><div class="map-modal-inner"><div class="map-modal-head"><h2>Body spatial perception</h2><button class="map-modal-close" onclick="closeMap()" aria-label="Close expanded map">×</button></div><div class="map-expanded-layout"><svg id="map-large" class="map-large" viewBox="0 0 12 12" aria-label="Expanded Body world map"></svg><div id="map-legend-large" class="scene-legend"><span class="muted">No scene available.</span></div></div></div></div>
<script>
const $=id=>document.getElementById(id);
async function get(path){const r=await fetch(path,{cache:'no-store'});if(!r.ok)throw Error(path+' '+r.status);return r.json()}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
 function renderSceneMap(map,wm){if(!map)return;const p=wm?.perception||{};const sim=wm?.sim||{};const objects=Array.isArray(p.objects)?p.objects:[];const sy=y=>12-(Number(y)||0);const pbody=p.body?.position||sim.body||[0,0];const shelf=sim.shelf||[1,9];const items=[];map.innerHTML='';map.insertAdjacentHTML('beforeend','<rect class="room" x="0" y="0" width="12" height="12"/>');for(let i=0;i<=12;i++){map.insertAdjacentHTML('beforeend',`<line class="grid" x1="${i}" y1="0" x2="${i}" y2="12"/><line class="grid" x1="0" y1="${i}" x2="12" y2="${i}"/>`)}map.insertAdjacentHTML('beforeend',`<circle class="goal" cx="${shelf[0]}" cy="${sy(shelf[1])}" r=".4"/><text class="marker-label" style="font-size:1.6px" x="${shelf[0]}" y="${sy(shelf[1])}">G</text>`);items.push({code:'G',cls:'goal',label:'Goal',detail:`target · (${Number(shelf[0]).toFixed(1)}, ${Number(shelf[1]).toFixed(1)})`});objects.forEach((o,index)=>{const q=o.position||[0,0];const cl=o.kind==='obstacle'?'obstacle':o.kind==='target'?'target':'object';const code=String(index+1);map.insertAdjacentHTML('beforeend',`<circle class="${cl}" cx="${q[0]}" cy="${sy(q[1])}" r="${Math.max(.22,Math.min(.55,Number(o.size||.4)/2))}"/><text class="marker-label" style="font-size:1.6px" x="${q[0]}" y="${sy(q[1])}">${code}</text>`);items.push({code,cls:cl,label:o.label||o.kind||'Object',detail:`${o.kind||'object'} · (${Number(q[0]).toFixed(1)}, ${Number(q[1]).toFixed(1)})`})});map.insertAdjacentHTML('beforeend',`<circle class="body" cx="${pbody[0]}" cy="${sy(pbody[1])}" r=".34"/><text class="marker-label" style="font-size:1.6px" x="${pbody[0]}" y="${sy(pbody[1])}">B</text>`);items.unshift({code:'B',cls:'body',label:'Body',detail:`agent · (${Number(pbody[0]).toFixed(1)}, ${Number(pbody[1]).toFixed(1)})`});const legendId=map.id==='map-large'?'map-legend-large':'map-legend';const legend=$(legendId);if(legend)legend.innerHTML=items.length?items.map(item=>`<div class="scene-item"><i class="${item.cls}">${esc(item.code)}</i><span><b>${esc(item.label)}</b><small>${esc(item.detail)}</small></span></div>`).join(''):'<span class="muted">No scene entities.</span>'}
 function renderMap(wm){renderSceneMap($('map'),wm);const large=$('map-large');if(large)renderSceneMap(large,wm);const p=wm?.perception||{};$('map-note').textContent=p.available?`Body observation from ${p.source}, ${p.age_seconds}s old.`:'No Body observation yet.'}
 function expandMap(){$('map-modal').classList.add('open');document.body.style.overflow='hidden'}
 function closeMap(){$('map-modal').classList.remove('open');document.body.style.overflow=''}
async function loadHomeAssistantSettings(){try{const s=await get('/plugins/home_assistant/settings');$('ha-url').value=s.url||'';$('ha-poll').value=s.poll_interval||5;$('ha-domains').value=s.allowed_domains||'';$('ha-entities').value=s.entities||'';$('ha-verify').checked=!!s.verify_ssl;$('ha-token').placeholder=s.token_configured?'Token configured; leave blank to keep it':'Enter a Home Assistant token'}catch(e){$('message').textContent='Home Assistant settings unavailable: '+e.message}}
async function saveHomeAssistantSettings(){const payload={url:$('ha-url').value,token:$('ha-token').value,poll_interval:Number($('ha-poll').value||5),allowed_domains:$('ha-domains').value,entities:$('ha-entities').value,verify_ssl:$('ha-verify').checked};try{const r=await fetch('/plugins/home_assistant/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error('save failed '+r.status);$('ha-token').value='';$('message').textContent='Home Assistant settings saved';await refresh()}catch(e){$('message').textContent='Home Assistant settings failed: '+e.message}}
async function togglePlugin(id,enabled){try{await fetch('/plugins/'+id,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled})});await refresh()}catch(e){$('message').textContent='Plugin update failed: '+e.message}}
async function refresh(){try{const h=await get('/health');const w=h.worldmodel||{};$('runtime').textContent=h.runtime||'—';$('mode').textContent=w.mode||'—';$('source').textContent=w.source?.source||'—';$('steps').textContent=w.steps??0;$('observation').textContent=w.perception?.available?`${w.perception.objects?.length||0} objects`:'none';$('plugins').innerHTML=(h.plugins||[]).map(p=>`<label class="plugin"><span><i class="dot ${p.enabled?'on':''}"></i><b>${esc(p.id)}</b><small>${esc(p.role||'')}</small></span><input type="checkbox" ${p.enabled?'checked':''} onchange="togglePlugin('${esc(p.id)}',this.checked)"/></label>`).join('')||'<span class="muted">No plugins registered.</span>';$('perception').textContent=w.perception?.available?JSON.stringify(w.perception,null,2):'Waiting for an observation. Enable the World Model or run a supervised step.';$('status').textContent=JSON.stringify(w,null,2);renderMap(w);$('message').textContent='Body connected';}catch(e){$('message').textContent='Body unavailable: '+e.message}}
async function step(){try{await fetch('/worldmodel/step',{method:'POST'});await refresh()}catch(e){$('message').textContent=e.message}}async function resetModel(){try{await fetch('/worldmodel/reset',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({clear_memory:false})});await refresh()}catch(e){$('message').textContent=e.message}}$('home-assistant-settings').hidden=false;loadHomeAssistantSettings();refresh();setInterval(refresh,3000);
</script></body></html>'''
